'use strict';
let editingTextId=null;
async function textBitmap(data){const size=Math.max(8,Math.min(500,+data.size||80)),lines=String(data.content).split('\n');if(lines.length>12)throw Error('Не больше 12 строк текста.');const family=['FragmentSans','FragmentSerif','FragmentMono'].includes(data.font)?data.font:'FragmentSans',spec=(data.italic?'italic ':'')+(data.bold?'700 ':'400 ')+size+'px '+family;await document.fonts.load(spec);const probe=off(1,1).getContext('2d');probe.font=spec;const pad=Math.ceil(size*.3),lineHeight=Math.ceil(size*1.4),width=Math.ceil(Math.max(...lines.map(line=>probe.measureText(line).width),1)+2*pad),height=lineHeight*lines.length+2*pad;if(width>12000||height>6000||width*height>16000000)throw Error('Текст слишком большой. Уменьшите размер шрифта или число строк.');const image=off(width,height),c=image.getContext('2d');c.font=spec;c.textBaseline='top';c.fillStyle=data.color||'#000000';lines.forEach((line,i)=>c.fillText(line,pad,pad+i*lineHeight));return image}
$('applyText').onclick=async()=>{const content=$('textContent').value;if(!content.trim()){toast('Введите текст');return}const data={content,font:$('textFont').value,size:Math.max(8,Math.min(500,+$('textSize').value||80)),bold:$('textBold').checked,italic:$('textItalic').checked,color:$('textColor').value},button=$('applyText');button.disabled=true;try{const image=await textBitmap(data),existing=layers.find(l=>l.id===editingTextId&&l.text);checkpoint();if(existing){existing.img=image;existing.text=data;existing.tint=null;existing.name=content.replace(/\s+/g,' ').slice(0,35);active=existing.id}else{const l={id:++seq,name:content.replace(/\s+/g,' ').slice(0,35),img:image,text:data,x:base.width/2,y:base.height/2,scale:1,angle:0,opacity:1,visible:true,tint:null};layers.push(l);active=l.id;editingTextId=l.id}selected=new Set([active]);selection=null;setMode('move');ui();button.textContent='Обновить текст';toast('Текст готов. Перемещайте и вращайте его как обычный объект.')}catch(e){toast(e.message||'Не удалось добавить текст')}finally{button.disabled=false}};
$('newText').onclick=()=>{editingTextId=null;$('textContent').value='';$('applyText').textContent='Добавить текст';$('textContent').focus()};
$('editText').onclick=()=>{const l=current();if(!l?.text)return;editingTextId=l.id;const d=l.text;$('textContent').value=d.content;$('textFont').value=d.font;$('textSize').value=d.size;$('textBold').checked=d.bold;$('textItalic').checked=d.italic;$('textColor').value=l.tint||d.color||'#000000';$('applyText').textContent='Обновить текст';switchTabs(['edit','text','project'],'text');if(window.innerWidth<=950){document.body.dataset.drawer='tools';$('toggleTools').setAttribute('aria-expanded','true');$('toggleInspector').setAttribute('aria-expanded','false');scheduleLayout()}};
